function prepareNewsletterEnrollment({ body, baseId, tableIdOrName }) {
  if (!body || typeof body !== "object" || Array.isArray(body))
    throw new Error("Provide a signup object.");
  const text = (value, label) => {
    if (typeof value !== "string" || !value.trim()) throw new Error("Provide " + label + ".");
    return value.trim();
  };
  const email = text(body.email, "one email address"),
    topic = text(body.topic, "a topic");
  // The single-address grammar used by HTML email fields; no display names or recipient lists.
  if (
    !/^[a-zA-Z0-9.!#$%&'*+\-/=?^_`{|}~]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?)*$/.test(
      email,
    )
  )
    throw new Error("Provide one email address.");
  if (email.includes("'"))
    throw new Error("This template does not support apostrophes in email addresses.");
  if (!["daily", "weekly", "surprise me"].includes(body.frequency))
    throw new Error("Choose daily, weekly or surprise me.");
  baseId = text(baseId, "your Airtable base ID");
  tableIdOrName = text(tableIdOrName, "your subscribers table ID");
  if (!/^app[a-zA-Z0-9]+$/.test(baseId) || !/^tbl[a-zA-Z0-9]+$/.test(tableIdOrName))
    throw new Error("Configure your own Airtable base and table IDs.");
  const fields = {
    Email: email,
    Topic: topic,
    Status: "active",
    Interval: body.frequency === "surprise me" ? "surprise" : body.frequency,
    "Start Day": ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"][new Date().getUTCDay()],
  };
  return {
    baseId,
    tableIdOrName,
    data: {
      fields,
      recipient: email,
      subject: "Learn something every day confirmation",
      message:
        'This is to confirm your request to subscribe to "Learn something every day!" - a free service to send you facts about your favourite topics.\n\nTopic: ' +
        topic +
        "\nSchedule: " +
        body.frequency,
    },
    endpoint: "/v0/" + baseId + "/" + tableIdOrName,
    payload: {
      typecast: false,
      performUpsert: { fieldsToMergeOn: ["Email"] },
      records: [{ fields }],
    },
  };
}

const settings = { baseId: "YOUR_AIRTABLE_BASE_ID", tableIdOrName: "YOUR_SUBSCRIBERS_TABLE_ID" };
return $input.all().map((item, index) => ({
  json: prepareNewsletterEnrollment({ body: item.json, ...settings }),
  pairedItem: { item: index },
}));

function verifyNewsletterSubscriber({ records, data, expectedId }) {
  if (!Array.isArray(records) || records.length !== 1)
    throw new Error("Airtable did not confirm one saved subscriber.");
  const record = records[0];
  if (
    !record ||
    typeof record.id !== "string" ||
    !/^rec[a-zA-Z0-9]+$/.test(record.id) ||
    (expectedId && record.id !== expectedId) ||
    !record.fields ||
    Object.entries(data.fields).some(([key, value]) => record.fields[key] !== value)
  )
    throw new Error("Airtable did not confirm the saved subscription fields.");
  return { recipient: data.recipient, subject: data.subject, message: data.message };
}

const savedItems = $input.all();
if (savedItems.length !== $("Prepare Newsletter Subscription").all().length)
  throw new Error("Airtable did not confirm one saved subscriber per signup.");
return savedItems.map((item, index) => ({
  json: verifyNewsletterSubscriber({
    records: [item.json],
    data: $("Prepare Newsletter Subscription").itemMatching(index).json.data,
    expectedId: "",
  }),
  pairedItem: { item: index },
}));

function confirmNewsletterEnrollment({ messageId }) {
  if (typeof messageId !== "string" || !messageId.trim())
    throw new Error("Gmail did not confirm acceptance of the confirmation email.");
  return { body: { subscribed: true, confirmationAccepted: true } };
}

return $input.all().map((item, index) => ({
  json: confirmNewsletterEnrollment({ messageId: item.json.id }),
  pairedItem: { item: index },
}));
